//! Checked-in batched density-threshold SPIR-V (G1 amortization vehicle).
//!
//! Same fill as `threshold.comp.spvasm`, new index math: one dispatch
//! covers N chunks (N <= MAXBATCH = 64). Invocation id spans chunks x
//! columns (`chunk = gid.x / 512`, `col = gid.x % 512`); q/out are
//! chunk-major flat arrays; dispatch is (8*N, 1, 1) with LocalSize 64.
//!
//! Source of truth is `threshold_batch.comp.spvasm`. Regenerated by
//! `zig build shaders` (spirv-as + spirv-val); manual fallback:
//!
//!   spirv-as --target-env vulkan1.0 threshold_batch.comp.spvasm -o threshold_batch.comp.spv
//!   spirv-val --target-env vulkan1.0 threshold_batch.comp.spv
//!
//! and commit both files. The binary embeds here via `@embedFile`.

const std = @import("std");

const bytes = @embedFile("threshold_batch.comp.spv");

pub const word_count: usize = bytes.len / 4;

comptime {
    if (bytes.len % 4 != 0) @compileError("threshold_batch.comp.spv size is not a whole word count");
}

/// Driver-ready u32 view (comptime-built from the embedded bytes).
pub const words: [word_count]u32 = blk: {
    @setEvalBranchQuota(20000);
    var w: [word_count]u32 = undefined;
    for (0..word_count) |i| {
        w[i] = std.mem.readInt(u32, bytes[i * 4 ..][0..4], .little);
    }
    break :blk w;
};

/// Contract (must match the shader source + `th` dims):
/// at most MAXBATCH chunks per dispatch, 512 columns each.
/// Dispatch cap guidance: RADV on GFX1201 (experimental driver) falls off
/// a cliff past ~200 groups (submit stays ~17µs, fence wait balloons
/// 10-100×; group-count trigger proven by --groups bisection, not buffer
/// size). Stay ≤128 groups (16 chunks) per dispatch and pipeline multiple
/// dispatches instead. Revisit when Mesa stabilizes GFX12 compute.
pub const MAXBATCH: usize = 64;
pub const Q_PER_CHUNK: usize = 825;
pub const CELLS_PER_CHUNK: usize = 16 * 256 * 16;
pub const COLS_PER_CHUNK: usize = 512;
pub const q_elems: usize = MAXBATCH * Q_PER_CHUNK;
pub const cells_elems: usize = MAXBATCH * CELLS_PER_CHUNK;
pub const q_bytes: usize = q_elems * 8;
pub const out_bytes: usize = cells_elems * 4;

/// Groups for N active chunks at LocalSize 64.
pub fn groupsFor(n_chunks: u32) u32 {
    return n_chunks * @as(u32, COLS_PER_CHUNK / 64);
}

test "batch spv header is Vulkan 1.0 with Float64 + NoContraction" {
    try std.testing.expectEqual(@as(u32, 0x07230203), words[0]);
    try std.testing.expectEqual(@as(u32, 0x00010000), words[1]);
    try std.testing.expectEqual(@as(usize, 997), word_count);
    var found_f64 = false;
    var nc_count: usize = 0;
    var i: usize = 5;
    while (i < word_count) {
        const w = words[i];
        const wc: usize = w >> 16;
        try std.testing.expect(wc >= 1);
        if (w == (@as(u32, 2) << 16) | 17) {
            try std.testing.expect(i + 1 < word_count);
            if (words[i + 1] == 10) found_f64 = true;
        }
        if (w == (@as(u32, 3) << 16) | 71) {
            try std.testing.expect(i + 2 < word_count);
            if (words[i + 2] == 42) nc_count += 1;
        }
        i += wc;
    }
    try std.testing.expectEqual(word_count, i);
    try std.testing.expect(found_f64);
    // Same 22 f64 arithmetic results as the single-chunk kernel (only
    // integer chunk-offset math was added — if this count moves, re-verify
    // bit-exactness, don't just bless the new number).
    try std.testing.expectEqual(@as(usize, 22), nc_count);
}

test "batch groups scale with chunk count" {
    try std.testing.expectEqual(@as(u32, 8), groupsFor(1));
    try std.testing.expectEqual(@as(u32, 64), groupsFor(8));
    try std.testing.expectEqual(@as(u32, 512), groupsFor(64));
}
